
(function(){const { $, read, write, uid, esc, money, date, today, notify }=window.OP;const KEY='np_inventario_compras_pymes_v1';let state=read(KEY,{products:[],suppliers:[],movements:[],purchases:[]});function persist(){write(KEY,state);render()}function render(){const low=state.products.filter(p=>Number(p.stock)<=Number(p.min));const value=state.products.reduce((s,p)=>s+Number(p.stock)*Number(p.cost),0);$('[data-kpi="products"]').textContent=state.products.length;$('[data-kpi="stockValue"]').textContent=money(value);$('[data-kpi="low"]').textContent=low.length;$('[data-kpi="suppliers"]').textContent=state.suppliers.length;const ps=$('#purchaseProduct'),old=ps.value;ps.innerHTML=state.products.length?state.products.map(p=>`<option value="${esc(p.id)}">${esc(p.sku)} · ${esc(p.name)} (${p.stock})</option>`).join(''):'<option value="">Primero crea un producto</option>';ps.value=old;const ss=$('#purchaseSupplier'),oldS=ss.value;ss.innerHTML='<option value="">Sin asignar</option>'+state.suppliers.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');ss.value=oldS;$('#productsTable').innerHTML=state.products.length?`<div class="op-table-wrap"><table class="op-table"><thead><tr><th>SKU / producto</th><th>Stock</th><th>Mínimo</th><th>Costo</th><th>Precio</th><th>Estado</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td><strong>${esc(p.sku)}</strong><br>${esc(p.name)}</td><td><strong>${p.stock}</strong></td><td>${p.min}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td><span class="op-tag ${p.stock<=p.min?'danger':'good'}">${p.stock<=p.min?'Reponer':'En stock'}</span></td><td><button class="op-button" data-out="${esc(p.id)}">Salida</button> <button class="op-button danger" data-delete-product="${esc(p.id)}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="op-empty">Aún no hay productos.</div>';$('#suppliersTable').innerHTML=state.suppliers.length?`<div class="op-table-wrap"><table class="op-table"><thead><tr><th>Empresa</th><th>Contacto</th><th>Teléfono</th><th>Correo</th><th>Condiciones</th><th></th></tr></thead><tbody>${state.suppliers.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.person)}</td><td>${esc(s.phone)}</td><td>${esc(s.email)}</td><td>${esc(s.terms)}</td><td><button class="op-button danger" data-delete-supplier="${esc(s.id)}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="op-empty">Aún no hay proveedores.</div>'}$('#productForm').addEventListener('submit',e=>{e.preventDefault();const p={id:uid(),sku:$('#sku').value.trim(),name:$('#productName').value.trim(),cost:Number($('#productCost').value||0),price:Number($('#productPrice').value||0),stock:Number($('#productStock').value||0),min:Number($('#productMin').value||0),createdAt:new Date().toISOString()};if(!p.sku||!p.name)return;if(state.products.some(x=>x.sku.toLowerCase()===p.sku.toLowerCase()))return notify('Ese SKU ya existe.','');state.products.unshift(p);e.target.reset();persist();notify('Producto guardado.','good')});$('#supplierForm').addEventListener('submit',e=>{e.preventDefault();const s={id:uid(),name:$('#supplierName').value.trim(),person:$('#supplierPerson').value.trim(),phone:$('#supplierPhone').value.trim(),email:$('#supplierEmail').value.trim(),terms:$('#supplierTerms').value.trim()};if(!s.name)return;state.suppliers.unshift(s);e.target.reset();persist();notify('Proveedor guardado.','good')});$('#purchaseForm').addEventListener('submit',e=>{e.preventDefault();const p=state.products.find(x=>x.id===$('#purchaseProduct').value);if(!p)return;const qty=Number($('#purchaseQty').value||0);if(qty<=0)return;p.stock+=qty;p.cost=Number($('#purchaseCost').value||p.cost);state.purchases.unshift({id:uid(),productId:p.id,supplierId:$('#purchaseSupplier').value,qty,cost:p.cost,date:$('#purchaseDate').value||today(),note:$('#purchaseNote').value.trim()});state.movements.unshift({id:uid(),productId:p.id,type:'in',qty,date:today(),reason:'Compra'});e.target.reset();persist();notify('Compra aplicada al stock.','good')});document.addEventListener('click',e=>{const out=e.target.closest('[data-out]')?.dataset.out;if(out){const p=state.products.find(x=>x.id===out);const qty=Number(prompt(`¿Cuántas unidades salen de ${p.name}?`,1));if(p&&qty>0&&qty<=p.stock){p.stock-=qty;state.movements.unshift({id:uid(),productId:p.id,type:'out',qty,date:today(),reason:'Salida manual'});persist();notify('Salida registrada.','good')}}const del=e.target.closest('[data-delete-product]')?.dataset.deleteProduct;if(del&&confirm('¿Eliminar este producto?')){state.products=state.products.filter(p=>p.id!==del);persist()}const ds=e.target.closest('[data-delete-supplier]')?.dataset.deleteSupplier;if(ds&&confirm('¿Eliminar este proveedor?')){state.suppliers=state.suppliers.filter(s=>s.id!==ds);persist()}});$('#clearInventory').addEventListener('click',()=>{if(confirm('¿Eliminar productos, proveedores y movimientos?')){state={products:[],suppliers:[],movements:[],purchases:[]};persist();notify('Inventario vacío.')}});render()})();